<?php
declare(strict_types=1); require_once __DIR__.'/config/database.php'; require_once __DIR__.'/config/ui.php'; $pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$c=srnu_obtener_cotizacion($id);if(!$c){http_response_code(404);exit('Cotización no encontrada');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['agregar'])){$m=max(0,(float)($_POST['monto']??0));if($m>0){$pdo->prepare('INSERT INTO pagos(cotizacion_id,fecha,metodo,monto,destinatario,notas,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([$id,$_POST['fecha']??date('Y-m-d'),trim($_POST['metodo']??'Transferencia'),$m,trim($_POST['destinatario']??'General'),trim($_POST['notas']??'')]);$pdo->prepare("UPDATE cotizaciones SET estado='Anticipo recibido',updated_at=NOW() WHERE id=? AND estado IN ('Cotización','Aprobada')")->execute([$id]);}}
 if(isset($_POST['registrar_anticipo']) && !empty($c['conservar_anticipo_recibido'])){$m=(float)$c['anticipo_recibido_monto'];if($m>0 && srnu_total_pagado($id)<=0){$ins=$pdo->prepare('INSERT INTO pagos(cotizacion_id,fecha,metodo,monto,destinatario,notas,created_at) VALUES(?,?,?,?,?,?,NOW())');if(!empty($c['dividir_anticipo'])){$partes=[['Sergio',(float)$c['anticipo_sergio']],['Ricardo',(float)$c['anticipo_ricardo']],['Tomás',(float)$c['anticipo_tomas']]];foreach($partes as [$persona,$monto])if($monto>0.009)$ins->execute([$id,$c['fecha'],'Transferencia',$monto,$persona,'Importado desde anticipo ya recibido']);}else{$ins->execute([$id,$c['fecha'],'Transferencia',$m,'General','Importado desde anticipo ya recibido']);}$pdo->prepare("UPDATE cotizaciones SET estado='Anticipo recibido',updated_at=NOW() WHERE id=? AND estado IN ('Cotización','Aprobada')")->execute([$id]);}}
 if(isset($_POST['eliminar_pago'])){$pdo->prepare('DELETE FROM pagos WHERE id=? AND cotizacion_id=?')->execute([(int)$_POST['pago_id'],$id]);}
 header('Location: pagos.php?id='.$id);exit;
}
$st=$pdo->prepare('SELECT * FROM pagos WHERE cotizacion_id=? ORDER BY fecha DESC,id DESC');$st->execute([$id]);$pagos=$st->fetchAll();$pagado=srnu_total_pagado($id);$saldo=max(0,(float)$c['total']-$pagado);
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="es"><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta charset="utf-8"><title>Pagos · <?=h($c['folio'])?></title><link rel="icon" href="favicon.png"><style>body{font-family:Arial;background:#f4f5f7;margin:0}.w{max-width:1000px;margin:30px auto;padding:0 18px}.p{background:#fff;padding:16px;border-radius:12px;margin:12px 0}a,.btn{display:inline-block;background:#111;color:#fff;padding:9px 12px;border-radius:7px;text-decoration:none;border:0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.big{font-size:26px;font-weight:bold}.form{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.form input,.form select{padding:10px;border:1px solid #ccc;border-radius:7px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #eee;text-align:left}@media(max-width:700px){.grid,.form{grid-template-columns:1fr}}</style><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><?php srnu_appbar('cotizaciones'); ?><div class="w"><a href="cotizaciones.php">← Cotizaciones</a> <a href="cotizador.php?id=<?=$id?>">Editar cotización</a><h1>Pagos · <?=h($c['folio'])?></h1><p><?=h($c['cliente'])?> · <?=h($c['vehiculo'])?></p><div class="grid"><div class="p">Total<div class="big">$<?=number_format((float)$c['total'],2)?></div></div><div class="p">Pagado<div class="big">$<?=number_format($pagado,2)?></div></div><div class="p">Saldo<div class="big">$<?=number_format($saldo,2)?></div></div></div>
<?php if(!empty($c['conservar_anticipo_recibido']) && $pagado<=0):?><div class="p"><form method="post"><input type="hidden" name="id" value="<?=$id?>"><p>Esta cotización tiene un anticipo histórico de <b>$<?=number_format((float)$c['anticipo_recibido_monto'],2)?></b> pero aún no existe como movimiento de pago.</p><button class="btn" name="registrar_anticipo">Registrar anticipo como pago</button></form></div><?php endif;?>
<div class="p"><h3>Registrar pago</h3><form method="post" class="form"><input type="hidden" name="id" value="<?=$id?>"><input type="date" name="fecha" value="<?=date('Y-m-d')?>" required><select name="metodo"><option>Transferencia</option><option>Efectivo</option><option>Tarjeta</option><option>Otro</option></select><input type="number" step="0.01" min="0.01" name="monto" placeholder="Monto" required><select name="destinatario"><option>General</option><option>Sergio</option><option>Ricardo</option><option>Tomás</option><option>IVA</option></select><input name="notas" placeholder="Notas"><button class="btn" name="agregar">Agregar pago</button></form></div>
<div class="p"><h3>Historial</h3><table><tr><th>Fecha</th><th>Método</th><th>Destinatario</th><th>Monto</th><th>Notas</th><th></th></tr><?php foreach($pagos as $p):?><tr><td><?=h($p['fecha'])?></td><td><?=h($p['metodo'])?></td><td><?=h($p['destinatario'])?></td><td>$<?=number_format((float)$p['monto'],2)?></td><td><?=h($p['notas'])?></td><td><form method="post" onsubmit="return confirm('¿Eliminar este pago?')"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="pago_id" value="<?=(int)$p['id']?>"><button name="eliminar_pago">✕</button></form></td></tr><?php endforeach;?></table></div></div></body></html>
